 cursorImg.style.left = e.clientX + 'px';
 cursorImg.style.top = e.clientY + 'px';
});

.timeline-wrapper {
 position: relative;
 height: 1800px;
}
/* Yellow moving box */
#scrollBox {
 width: 25px;
 height: 35px;
 background: #f4b400;
 position: absolute;
 left: -11px;
 top: 0;
 border-radius: 2px;
}
.visible-xs{display:none!important}
@media only screen and (max-width : 767px) {
 .timeline-wrapper {
 position: relative;
 height: 4600px;
}
.hidden-xs{display:none!important}
.visible-xs{display:block!important}
}
